/// <summary>
/// Test class for SOrderTable initialization.
/// </summary>
internal final class SOrderTableTest
{
}

Method.Source:
/// <summary>
/// Tests default values when creating a new order.
/// </summary>
public static void testInitValue()
{
    SOrderTable orderTable;
    orderTable.initValue();

    if (orderTable.Status != SOrderStatus::Draft)
    {
        throw Exception::Error;
    }

    if (orderTable.TotalAmount != 0)
    {
        throw Exception::Error;
    }
}
